const findings = {
  2: ["Align QMS context with organizational direction", "Identified issues are not consistently linked to the laboratory’s purpose, strategy, or service priorities.", "The context-review process does not define strategic-relevance criteria or require leadership approval."],
  3: ["Establish periodic context review", "Internal and external issues are not monitored at defined intervals.", "No owner, review frequency, change trigger, or management-review input is defined."],
  5: ["Monitor interested-party requirements", "Interested-party requirements are recorded but not routinely reviewed.", "The register has no review owner, frequency, or change-notification trigger."]
};
const questions = [
  [1,"4.1","Has the organization identified relevant internal and external issues affecting the QMS?","yes"],
  [2,"4.1","Are the identified issues relevant to the organization’s purpose and strategic direction?","no"],
  [3,"4.1","Are the identified internal and external issues periodically monitored and reviewed?","no"],
  [4,"4.2","Has the organization identified relevant interested parties and their requirements?","yes"],
  [5,"4.2","Are interested parties and their requirements regularly monitored and reviewed?","no"],
  [6,"4.3","Has the organization clearly defined the boundaries and applicability of the QMS?","yes"],
  [7,"5.1","Does top management take responsibility for the effectiveness of the QMS?","yes"],
  [8,"5.2","Is the quality policy documented, communicated, and understood?","yes"],
  [9,"6.1","Is the effectiveness of actions taken regularly evaluated?","na"]
];
const style=`*{box-sizing:border-box}body{margin:0;background:#f5f7f4;color:#13231d;font:14px Arial}a{text-decoration:none;color:inherit}.shell{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.side{position:fixed;inset:0 auto 0 0;width:230px;height:100vh;background:#102b24;color:#fff;padding:26px 18px;display:flex;flex-direction:column}.brand{font-size:19px;font-weight:800;margin:0 8px 35px}.brand i{display:inline-grid;place-items:center;width:38px;height:38px;background:#d9f46b;color:#17382f;border-radius:12px;margin-right:10px}.nav small{display:block;color:#789289;text-transform:uppercase;letter-spacing:.14em;margin:20px 12px 8px}.nav a{display:block;padding:13px 14px;color:#bcd0c9;border-radius:10px;margin:4px 0;font-weight:700}.nav a.on,.nav a:hover{background:#21443a;color:#fff}.foot{margin-top:auto;background:#173a30;border:1px solid #2d5147;border-radius:13px;padding:14px;color:#a9bdb6}.main{grid-column:2;padding:38px 4vw 70px;max-width:1450px;width:100%}.head{display:flex;justify-content:space-between;align-items:end;margin-bottom:26px}.kicker{font-size:10px;color:#0b7251;text-transform:uppercase;letter-spacing:.14em;font-weight:800}h1{font-size:34px;margin:5px 0 7px}h2{margin:4px 0 10px;font-size:18px}.muted,.head p,.card p{color:#6d7b75;line-height:1.6}.summary,.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.summary,.metric,.panel,.card,.sidecard{background:#fff;border:1px solid #e2e8e4;border-radius:15px;padding:20px}.summary span,.metric span{display:block;color:#6d7b75;font-size:11px}.summary strong,.metric strong{font-size:25px;display:block;margin-top:6px}.toolbar{display:flex;justify-content:space-between;margin:20px 0}.search{padding:11px 15px;border:1px solid #dfe6e2;border-radius:10px;background:#fff;min-width:300px}.filters button,.answers button{border:1px solid #dfe6e2;padding:8px 12px;background:#fff;font-weight:800}.filters .on{background:#0b7251;color:#fff}.qlist{display:grid;gap:11px}.q{background:#fff;border:1px solid #e2e8e4;border-radius:14px;padding:20px;display:grid;grid-template-columns:45px 1fr}.q.no{border-color:#eaa9a4;box-shadow:inset 4px 0 #c53a35}.num{color:#93a19b;font-weight:800}.meta{font-size:10px;color:#0b7251;text-transform:uppercase;font-weight:800}.q h2{font-size:15px;margin:7px 0 15px}.answers{display:flex;gap:7px}.answers button{border-radius:8px;font-size:11px}.q.yes .yes,.q.na .na{background:#e7f4ee;color:#0b7251}.q.no .no{background:#fff0ee;color:#c53a35}.open{margin-left:auto;background:#fff0ee;color:#c53a35;padding:8px 12px;border-radius:8px;font-size:11px;font-weight:800}.metric:first-child{background:#102b24;color:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:14px 0}.bars>div{margin:18px 0}.bars label{display:flex;justify-content:space-between}.bar{height:8px;background:#edf0ee;border-radius:9px;margin-top:7px}.bar i{display:block;height:100%;background:#0b7251}.bar .red{background:#c53a35}.bar .amber{background:#bb7517}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:14px;border-top:1px solid #e2e8e4}th{font-size:10px;color:#75827c;text-transform:uppercase}.redlink{color:#c53a35;font-weight:800}.pill{padding:5px 9px;border-radius:20px;background:#fff0ee;color:#c53a35;font-size:10px;font-weight:800}.hero{background:#102b24;color:#fff;border-radius:16px;padding:23px;margin-bottom:14px}.hero blockquote{margin:15px 0 0;display:flex;justify-content:space-between}.hero b{color:#ff9790}.cgrid{display:grid;grid-template-columns:1.8fr .7fr;gap:14px}.stack{display:grid;gap:12px}.danger{border-left:4px solid #c53a35}.smart{background:#e9f5ef;border-color:#bedccd}.sidecard{margin-bottom:12px}.progress{height:9px;background:#e7ece9;border-radius:8px}.progress i{display:block;height:100%;background:#0b7251;border-radius:8px}.fish{overflow:hidden;border-color:#efcbc7}.fishhead{display:flex;justify-content:space-between}.fishstage{height:315px;position:relative}.spine{position:absolute;left:5%;right:16%;top:50%;height:3px;background:#c53a35;animation:draw .8s}.spine:after{content:"";position:absolute;right:-10px;top:-5px;border-left:12px solid #c53a35;border-top:6px solid transparent;border-bottom:6px solid transparent}.effect{position:absolute;right:0;top:50%;transform:translateY(-50%);background:#c53a35;color:#fff;width:125px;height:82px;border-radius:50% 15px 15px 50%;display:grid;place-content:center;text-align:center;animation:pop .6s}.cause{position:absolute;top:50%;width:120px;height:130px;border:0;background:none;cursor:pointer;opacity:0;animation:fade .4s var(--d) forwards}.cause.top{transform:translate(-50%,-100%)}.cause.bottom{transform:translate(-50%,0)}.cause:before{content:"";position:absolute;left:50%;width:2px;height:75px;background:#df8d88}.cause.top:before{bottom:0;transform:rotate(-34deg)}.cause.bottom:before{top:0;transform:rotate(34deg)}.cause b,.cause small{display:block;position:absolute;text-align:left;color:#c53a35}.cause small{color:#65736d;font-size:9px}.cause.top b{top:15px}.cause.top small{top:35px}.cause.bottom b{bottom:43px}.cause.bottom small{bottom:5px}.cause.active b{background:#c53a35;color:#fff;padding:4px;border-radius:5px}.detail{background:#fff0ee;border:1px solid #efc0bb;border-radius:10px;padding:13px;animation:fade .3s}.detail b{color:#c53a35}@keyframes draw{from{transform:scaleX(0)}}@keyframes pop{from{opacity:0;transform:translate(20px,-50%) scale(.8)}}@keyframes fade{to{opacity:1}}@media(max-width:800px){.shell{display:block}.side{position:static;width:auto;height:auto}.foot{display:none}.nav a{display:inline-block}.main{padding:24px 15px}.summary,.metrics,.grid,.cgrid{grid-template-columns:1fr}.fishstage{height:auto;display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:15px 0}.spine,.effect{display:none}.cause,.cause.top,.cause.bottom{position:static;transform:none;width:auto;height:80px;border:1px solid #efcbc7;background:#fff7f6;border-radius:9px;padding:10px;text-align:left}.cause:before{display:none}.cause b,.cause small,.cause.top b,.cause.top small,.cause.bottom b,.cause.bottom small{position:static}.toolbar{display:block}.search{width:100%;margin-bottom:10px}}`;
const script=`document.addEventListener("click",e=>{let a=e.target.closest("[data-a]");if(a){let q=a.closest(".q");q.className="q "+a.dataset.a;}let c=e.target.closest(".cause");if(c){document.querySelectorAll(".cause").forEach(x=>x.classList.remove("active"));c.classList.add("active");document.querySelector(".detail").innerHTML="<b>"+c.dataset.name+"</b><p>"+c.dataset.ev+"</p>";}})`;
function shell(path,title,subtitle,body){return`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${title}</title><style>${style}</style></head><body><div class="shell"><aside class="side"><a href="/" class="brand"><i>◈</i>LQTM Audit Hub</a><nav class="nav"><small>Workspace</small><a class="${path==="/"?"on":""}" href="/">▣ &nbsp; Audit</a><a class="${path==="/dashboard"?"on":""}" href="/dashboard">◫ &nbsp; Analysis</a><a class="${path.startsWith("/capa")?"on":""}" href="/capa/2">⚠ &nbsp; CAPA</a></nav><div class="foot">● Internal audit<br><small>Draft · Jul 2026</small></div></aside><main class="main"><header class="head"><div><span class="kicker">ISO 9001:2015</span><h1>${title}</h1><p>${subtitle}</p></div></header>${body}</main></div><script>${script}</script></body></html>`}
function audit(){let qs=questions.map((q,i)=>`<article class="q ${q[3]}"><div class="num">${String(i+1).padStart(2,"0")}</div><div><span class="meta">Clause ${q[1]}</span><h2>${q[2]}</h2><div class="answers"><button class="yes" data-a="yes">✓ YES</button><button class="no" data-a="no">⚠ NO</button><button class="na" data-a="na">N/A</button>${q[3]==="no"?`<a class="open" href="/capa/${q[0]}">Open finding →</a>`:""}</div></div></article>`).join("");return shell("/","Laboratory quality audit","Assess each requirement and open a CAPA when a response is nonconforming.",`<section class="summary"><div><span>Questions</span><strong>9</strong></div><div><span>Answered</span><strong>9/9</strong></div><div><span>Conforming</span><strong>56%</strong></div><div><span>Audit progress</span><strong>100%</strong></div></section><div class="toolbar"><input class="search" placeholder="Search question or clause"><div class="filters"><button class="on">All</button><button>YES</button><button>NO</button><button>N/A</button></div></div><div class="qlist">${qs}</div>`)}
function dashboard(){let rows=Object.entries(findings).map(([id,f])=>`<tr><td><a class="redlink" href="/capa/${id}">${f[0]}</a></td><td><span class="pill">${id==="5"?"Medium":"High"}</span></td><td>Quality Manager</td><td>Dec 2026</td><td>${id==="2"?"22":id==="3"?"10":"45"}%</td></tr>`).join("");return shell("/dashboard","Audit dashboard","A decision-ready view of conformance, findings, ownership, and CAPA progress.",`<section class="metrics"><div class="metric"><span>Conformance rate</span><strong>63%</strong><small>5 of 8 applicable controls</small></div><div class="metric"><span>Open findings</span><strong>3</strong></div><div class="metric"><span>CAPA completion</span><strong>26%</strong></div><div class="metric"><span>Evidence coverage</span><strong>67%</strong></div></section><section class="grid"><article class="panel"><span class="kicker">Clause health</span><h2>Performance by section</h2><div class="bars"><div><label>4.1 Context <b>33%</b></label><div class="bar"><i class="red" style="width:33%"></i></div></div><div><label>4.2 Interested parties <b>50%</b></label><div class="bar"><i class="amber" style="width:50%"></i></div></div><div><label>4.3 Scope <b>100%</b></label><div class="bar"><i style="width:100%"></i></div></div></div></article><article class="panel"><span class="kicker">Overall analysis</span><h2>Context governance is the key gap</h2><p class="muted">Issues are identified, but strategic alignment, review triggers, ownership, and effectiveness evidence remain incomplete.</p></article></section><section class="panel"><h2>Nonconformities & CAPA</h2><table><thead><tr><th>Finding</th><th>Priority</th><th>Owner</th><th>Due</th><th>Progress</th></tr></thead><tbody>${rows}</tbody></table></section>`)}
function capa(id){let q=questions.find(x=>x[0]===+id)||questions[1],f=findings[id]||findings[2];let cs=[["Method","No controlled review method","The procedure lacks criteria, frequency, and approval."],["People","Ownership is unclear","No accountable role is assigned."],["Measurement","No effectiveness criteria","Success measures documents, not adequacy."],["System","Review is not workflow-driven","Context review is absent from management review."],["Environment","Changes are not triggers","Regulatory, market, technology, and climate changes do not initiate review."],["Records","Evidence is not retained","Approvals, decisions, and actions are not consistently recorded."]];let branches=cs.map((c,i)=>`<button class="cause ${i%2?"bottom":"top"} ${i===0?"active":""}" style="left:${13+i*14.3}%;--d:${i*.12}s" data-name="${c[0]} · ${c[1]}" data-ev="${c[2]}"><b>${c[0]}</b><small>${c[1]}</small></button>`).join("");return shell(`/capa/${id}`,f[0],`Finding NC-${String(q[0]).padStart(3,"0")} · Clause ${q[1]}`,`<section class="hero"><span class="pill">HIGH · OPEN</span><blockquote><span>${q[2]}</span><b>NO</b></blockquote></section><section class="cgrid"><div class="stack"><article class="card"><span class="kicker">Finding</span><h2>Observed nonconformity</h2><p>${f[1]}</p></article><article class="card danger"><span class="kicker">Root cause</span><h2>Systemic cause</h2><p>${f[2]}</p></article><article class="card fish"><div class="fishhead"><div><span class="kicker">Cause & effect analysis</span><h2>Interactive fishbone · 6M</h2></div><b style="color:#c53a35">● Click a cause</b></div><div class="fishstage"><div class="spine"></div><div class="effect"><small>EFFECT</small><b>QMS context gap</b></div>${branches}</div><div class="detail"><b>Method · No controlled review method</b><p>${cs[0][2]}</p></div></article><article class="card"><span class="kicker">Corrective action</span><h2>Prevent recurrence</h2><p>Revise the procedure to define criteria, ownership, review triggers, approval evidence, and retained records.</p></article><article class="card smart"><span class="kicker">SMART objective</span><h2>By 15 December 2026, review 100% of documented issues against approved criteria and obtain Director approval.</h2></article></div><aside><div class="sidecard"><span class="kicker">Execution</span><h2>Action control</h2><p><b>Responsible</b><br>Quality Manager</p><p><b>Monitoring</b><br>Director</p><p><b>Due</b><br>15 Dec 2026</p></div><div class="sidecard"><span class="kicker">Progress</span><h2>22% complete</h2><div class="progress"><i style="width:22%"></i></div></div></aside></section>`)}
export default{async fetch(req){let p=new URL(req.url).pathname;let html=p==="/dashboard"?dashboard():p.startsWith("/capa/")?capa(p.split("/")[2]):audit();return new Response(html,{headers:{"content-type":"text/html;charset=utf-8"}})}};
